"""Exact platform exhibition catalogue; no merchant, scene, payment or store assumptions."""
import base64,binascii,hashlib,json,re
from scripts.pr122_customer_core import canonical

CHANNEL='COMMUNITY_PLATFORM_SHOWCASE_V1'
SLOT='AXSC-001'  # public label only; record address is a server-generated hash.
OPS=('community.item','community.merchant_settings')
ROUTE='/community/operations'

GALLERY=[('07710598c97dd7e2b5fcdc060fc7f2f344850d96efd02e583a68082a0f6ffe88', '供货实拍 · 果园挂果', '供货方提供', '', '', ''), ('6d849a0a4cdabfd7f55ff3c73be3afba65bf752367289bbe219d0d3fe854dc73', '供货实拍 · 剥开果肉', '供货方提供', '', '', ''), ('51d6ab579e2fa5dd8ec3d15449715c1be761f356e95e9257f34d3055ad40b531', '外形与果瓣示意', 'Ivar Leidus，《Pomelo fruit.jpg》', 'https://commons.wikimedia.org/wiki/File:Pomelo_fruit.jpg', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0/'), ('a81303375a59f94c367a839d05d77b7c280b35dcafc37f9fa2e09ba395ffae81', '果肉近景示意', 'Allen Timothy Chang，《Pummelo flesh.jpg》', 'https://commons.wikimedia.org/wiki/File:Pummelo_flesh.jpg', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0/')]
PREFIX='data:image/jpeg;base64,'
BRAND_COVER='data:image/png;base64,'
BRAND_COVER_SHA256='fcb92ad5706c21218d1ffb4ed835227833ed507f33520de8c9e8289e2a651f50'

def gallery(value):
    if type(value) is not list or len(value)!=4 or any(type(v) is not str for v in value) or sum(map(len,value))>600000:
        raise ValueError('INVALID_SHOWCASE_GALLERY')
    result=[]
    for image,(digest,label,credit,source,license_,license_url) in zip(value,GALLERY):
        if len(image)>165000 or not image.startswith(PREFIX):
            raise ValueError('INVALID_SHOWCASE_GALLERY')
        try: raw=base64.b64decode(image[len(PREFIX):],validate=True)
        except (binascii.Error,ValueError):raise ValueError('INVALID_SHOWCASE_GALLERY') from None
        if hashlib.sha256(raw).hexdigest()!=digest:
            raise ValueError('INVALID_SHOWCASE_GALLERY_ASSET')
        result.append(dict(image_data=image,label=label,credit=credit,source=source,
                           license=license_,license_url=license_url,edited=bool(source)))
    return result

class Showcase:
    def __init__(self,center,*,project,tenant,operator_uid,workspace):
        if not all(type(v) is str and re.fullmatch(r'[A-Za-z0-9_-]{1,64}',v) for v in (project,tenant,operator_uid,workspace)):
            raise ValueError('INVALID_PROTECTED_PLATFORM_CATALOG')
        self.center,self.project,self.tenant,self.operator_uid,self.workspace=center,project,tenant,operator_uid,workspace
        self.key=hashlib.sha256(canonical(['platform-showcase',project,tenant])).hexdigest()
        self.aad=CHANNEL+':'+self.key

    def _read(self):
        r=self.center.db.execute('SELECT user_id,payload FROM links WHERE channel=? AND subject_idx=? AND project=? AND active=1',
                                 (CHANNEL,self.key,self.project)).fetchone()
        if r is None:return None
        record=json.loads(self.center.decrypt(r['payload'],self.aad))
        if r['user_id']!=self.operator_uid or record.get('project')!=self.project or record.get('tenant')!=self.tenant:
            raise PermissionError('PLATFORM_CATALOG_SCOPE_CHANGED')
        return record

    def dispatch(self,session,csrf,body):
        a=getattr(self.center,'community_admin_authority',None)
        if not a or a.c is not self.center or body['operation'] not in OPS or body['workspace']!=self.workspace:
            raise PermissionError('ORIGINAL_PLATFORM_CATALOG_REQUIRED')
        with self.center.tx():
            proof=a.authorize(session,csrf,ROUTE,body['operation'],workspace=self.workspace)
            if (proof.get('uid'),proof.get('project'),proof.get('tenant'))!=(self.operator_uid,self.project,self.tenant):
                raise PermissionError('ORIGINAL_PLATFORM_CATALOG_REQUIRED')
            if a.authority(self.operator_uid).get('kind')!='ROOT':
                raise PermissionError('ORIGINAL_PLATFORM_CATALOG_REQUIRED')
            old=self._read()
            p=body['params']
            if body['operation']=='community.merchant_settings':
                if p!={}:raise ValueError('INVALID_PLATFORM_CATALOG_READ')
                return dict(label='爱心商城',display_number=SLOT,display_only=True,record=old)
            fields={'expected_version','id','name','description','image_data','unit_minor','quantity','published'}
            if type(p) is not dict or set(p) not in (fields,fields|{'gallery'}) or type(p['expected_version']) is not int or p['expected_version']!=(old['version'] if old else 0):
                raise ValueError('PLATFORM_CATALOG_VERSION_OR_FIELDS')
            if (not all(type(p[k]) is str and 0<len(p[k])<=n for k,n in [('id',64),('name',120),('description',2000),('image_data',750000)])
                or not re.fullmatch(r'[A-Za-z0-9_-]{1,64}',p['id']) or old and p['id']!=old['id']
                or not re.fullmatch(r'data:image/jpeg;base64,/9j/[A-Za-z0-9+/]*={0,2}',p['image_data'])
                or type(p['unit_minor']) is not int or not 1<=p['unit_minor']<=100000000
                or type(p['quantity']) is not int or not 0<=p['quantity']<=100000000 or type(p['published']) is not bool):
                raise ValueError('INVALID_PLATFORM_CATALOG_ITEM')
            if 'gallery' in p and gallery(p['gallery'])[0]['image_data']!=p['image_data']:
                raise ValueError('SHOWCASE_PRIMARY_MISMATCH')
            record=dict(p,project=self.project,tenant=self.tenant,version=p['expected_version']+1)
            del record['expected_version']
            self.center.db.execute('INSERT INTO links VALUES(?,?,?,?,?,1) ON CONFLICT(channel,subject_idx,project) DO UPDATE SET payload=excluded.payload,active=1',
                (CHANNEL,self.key,self.operator_uid,self.project,self.center.encrypt(canonical(record),self.aad)))
            self.center.audit(self.project,self.operator_uid,'PLATFORM_SHOWCASE_SAVED',self.key)
            return dict(version=record['version'],published=record['published'],display_only=True)

    def public(self,identity,uid,*,detail=False):
        if identity.center is not self.center:return None
        # Native mini consumers intentionally have no project staff membership.
        # Reuse their exact server-admitted live consumer mapping, never a grant
        # or a caller-supplied tenant. Revoked native markers cannot fall back.
        from scripts import community_wechat_registration as registration
        if registration.native(self.center,uid) is not None:
            project=None
            for scene,binding in identity.scenes.items():
                if binding['project']!=self.project:continue
                try:project=registration.project(identity,uid,scene)
                except PermissionError:continue
                if project['tenant']==self.tenant:break
            if project is None:return None
        else:
            try:
                project,_,_=self.center.project(uid,self.project,('OWNER','EDITOR','VIEWER','REVIEWER'))
            except PermissionError:
                return None
        if project['tenant']!=self.tenant:return None
        row=self._read()
        if not row or not row['published']:return None
        result=dict(id=self.key,name='爱心商城',description=row['name'], category_id=None,category_name=None,
                    category_state='NOT_CONFIGURED',storefront_photo=None,photo_state='NOT_CONNECTED',
                    platform_self_operated=False,scene=None,version=row['version'],profile_version=row['version'],
                    platform_showcase=True,display_number=SLOT)
        result['showcase_cover']=dict(image_data=BRAND_COVER,label='爱心商城品牌图')
        if detail:
            result['showcase_item']={k:row[k] for k in ('id','name','description','image_data','unit_minor','quantity')}
            result['showcase_item'].update(available=False,display_only=True)
            if 'gallery' in row:result['showcase_item']['gallery']=gallery(row['gallery'])[:2]
        return result

def mount(ops,config):
    """Protected host plan only; no runtime changes to platform authority."""
    from scripts.community_admin_authority import CommunityAdminAuthority
    if type(config) is not dict or set(config)!={'project','tenant','operator_uid','workspace'}:
        raise ValueError('EXACT_PROTECTED_PLATFORM_SHOWCASE_CONFIG_REQUIRED')
    instance=Showcase(ops.center,**config)
    a=getattr(ops.center,'community_admin_authority',None)
    if (type(a) is not CommunityAdminAuthority or a.c is not ops.center
        or (a.project,a.tenant)!=(instance.project,instance.tenant)
        or instance.workspace in ops.grants or getattr(ops,'platform_showcase',None) is not None):
        raise PermissionError('ORIGINAL_PLATFORM_CATALOG_REQUIRED')
    operator=a.authority(instance.operator_uid)
    if (operator.get('kind')!='ROOT' or not {ROUTE+'#'+v for v in OPS}<=set(operator['capabilities'])
            or ROUTE+'#'+instance.workspace not in operator['workspace_scopes']):
        raise PermissionError('ORIGINAL_PLATFORM_CATALOG_SCOPE_NOT_PRESENT')
    ops.platform_showcase=instance
    return instance
